#!/usr/bin/env bash
# pre-push-quality-gates.sh
# Generated by gsd | Template: pre-push-quality-gates.sh.tmpl
#
# Pre-push hook: runs the workspace's discovered local quality gates
# (lint, format, typecheck, test, build) before a push and BLOCKS the push
# (exit 1) if any gate fails. This is the local half of the unified CI +
# local-gating primitive (P-019): because remote CI is intentionally minimal
# and Linux-only, local verification is the primary gate before push.
#
# Behavior:
#   * Absent gates are omitted at install time (only discovered gates appear).
#   * If a gate's tool is not installed on this machine, the gate is SKIPPED
#     with a warning (tool-not-found -> warn+skip), never a hard failure.
#   * EXCEPTION (P-019 required-gate carve-out): a gate declared REQUIRED
#     (run_required_gate) FAILS when its tool is absent, naming the install
#     command and the `git push --no-verify` escape. markdownlint is the
#     first and only required gate.
#   * Single deterministic pass — NO retry loop, so the hook cannot spin
#     (circuit-breaker compatible). A failing gate surfaces immediately.
#
# Install (opt-in — the harness never silently overwrites your .git/hooks):
#   Git invokes the hook by the exact name `pre-push` (no extension) under the
#   active hooks path, so this script must be INSTALLED AS `pre-push`:
#     * Default hooks path:
#         cp <this> .git/hooks/pre-push && chmod +x .git/hooks/pre-push
#     * Or a dedicated hooks directory referenced by core.hooksPath, where the
#       file (or a dispatcher that execs it) is named `pre-push`:
#         install -m 0755 <this> <hooks-dir>/pre-push
#         git config core.hooksPath <hooks-dir>
#   Pointing core.hooksPath at a directory that only contains
#   `pre-push-quality-gates.sh` will NOT work — git looks for `<dir>/pre-push`.
#   To bypass once (e.g. an emergency push): git push --no-verify
#
# git passes "<remote> <url>" as arguments and ref lines on stdin; a quality
# gate runs regardless of what is being pushed, so stdin is drained and ignored.

set -uo pipefail

# Run from repo root so repo-root-relative gate commands are valid.
GIT_TOPLEVEL="$(git rev-parse --show-toplevel)" || exit 1
cd "$GIT_TOPLEVEL" || exit 1
REPO_ROOT="$(pwd -P)" || exit 1

case "$GIT_TOPLEVEL" in
  [A-Za-z]:/*)
    CEILING_SEP=";"
    CEILING_ROOT="$GIT_TOPLEVEL"
    ;;
  *)
    CEILING_SEP=":"
    CEILING_ROOT="$REPO_ROOT"
    ;;
esac

DEFAULT_AGENT_TEMP_DIR="$REPO_ROOT/.gsd/runtime/tmp"
AGENT_TEMP_DIR="${AGENT_TEMP_DIR:-}"
AGENT_TEMP_DIR="${AGENT_TEMP_DIR%$'\r'}"
AGENT_TEMP_DIR="${AGENT_TEMP_DIR//\\//}"

validate_candidate_temp_dir() {
  cand="$1"
  [ -n "$cand" ] || return 1
  if [ "$CEILING_ROOT" != "$REPO_ROOT" ]; then
    case "$cand" in
      "$CEILING_ROOT"/*) cand="${REPO_ROOT}/${cand#"$CEILING_ROOT"/}" ;;
    esac
  fi
  case "$cand" in
    *$'\n'*|*$'\r'*|*:*|*\;*|..|*/..|../*|*/../*) return 1 ;;
  esac
  case "$cand" in
    /*) ;;
    *) cand="$REPO_ROOT/${cand#./}" ;;
  esac
  while :; do
    collapsed="${cand//\/\///}"
    [ "$collapsed" = "$cand" ] && break
    cand="$collapsed"
  done
  while [ "${cand%/}" != "$cand" ]; do
    cand="${cand%/}"
  done
  case "$cand" in
    "$REPO_ROOT"/*) ;;
    *) return 1 ;;
  esac
  rel="${cand#"$REPO_ROOT"/}"
  case "$rel" in
    .[gG][iI][tT]|.[gG][iI][tT]/*) return 1 ;;
  esac
  cur="$REPO_ROOT"
  IFS="/" read -r -a _segs <<< "$rel"
  for seg in "${_segs[@]}"; do
    [ -n "$seg" ] || continue
    if [ "$seg" = "." ] || [ "$seg" = ".." ]; then
      return 1
    fi
    cur="$cur/$seg"
    if [ -L "$cur" ] || { [ -e "$cur" ] && [ ! -d "$cur" ]; }; then
      return 1
    fi
  done
  AGENT_TEMP_DIR="$cand"
  return 0
}

if ! validate_candidate_temp_dir "$AGENT_TEMP_DIR"; then
  AGENT_TEMP_DIR="$DEFAULT_AGENT_TEMP_DIR"
fi

rel_final="${AGENT_TEMP_DIR#"$REPO_ROOT"/}"
cur_check="$REPO_ROOT"
IFS="/" read -r -a _final_segs <<< "$rel_final"
for seg in "${_final_segs[@]}"; do
  [ -n "$seg" ] || continue
  cur_check="$cur_check/$seg"
  if [ -L "$cur_check" ] || { [ -e "$cur_check" ] && [ ! -d "$cur_check" ]; }; then
    echo "ERROR: refusing symlink or non-directory ancestor in AGENT_TEMP_DIR: $cur_check" >&2
    exit 1
  fi
done

mkdir -p "$AGENT_TEMP_DIR" || exit 1
[ -d "$AGENT_TEMP_DIR" ] && [ ! -L "$AGENT_TEMP_DIR" ] || exit 1
RESOLVED_AGENT_TEMP_DIR="$(cd -P -- "$AGENT_TEMP_DIR" && pwd -P)" || exit 1
[ "$RESOLVED_AGENT_TEMP_DIR" = "$AGENT_TEMP_DIR" ] || exit 1
case "$RESOLVED_AGENT_TEMP_DIR" in
  "$REPO_ROOT"/*) ;;
  *) exit 1 ;;
esac

export AGENT_TEMP_DIR
export TEMP="$AGENT_TEMP_DIR"
export TMP="$AGENT_TEMP_DIR"
export TMPDIR="$AGENT_TEMP_DIR"

append_git_ceiling() {
  val="$1"
  [ -n "$val" ] || return 0
  if [ -z "${GIT_CEILING_DIRECTORIES:-}" ]; then
    GIT_CEILING_DIRECTORIES="$val"
    return 0
  fi
  case "${CEILING_SEP}${GIT_CEILING_DIRECTORIES}${CEILING_SEP}" in
    *"${CEILING_SEP}${val}${CEILING_SEP}"*) ;;
    *) GIT_CEILING_DIRECTORIES="${GIT_CEILING_DIRECTORIES}${CEILING_SEP}${val}" ;;
  esac
}

append_git_ceiling "$AGENT_TEMP_DIR"
if [ "$CEILING_ROOT" != "$REPO_ROOT" ]; then
  append_git_ceiling "${CEILING_ROOT}/${AGENT_TEMP_DIR#"$REPO_ROOT"/}"
fi
export GIT_CEILING_DIRECTORIES

# Drain stdin (ref updates) so git does not see a broken pipe.
cat >/dev/null 2>&1 || true

FAILED=0

# run_gate <label> <probe_tool> <command>
# Probes <probe_tool> — the discovered gate binary whose absence means "skip".
# When <probe_tool> is empty, falls back to the command's leading real token
# (skipping leading VAR=value env prefixes). Explicit probe metadata makes
# wrapper commands such as `python -m mypy` or `npm run lint` skip correctly when
# the REAL tool (mypy, the lint script) is absent, instead of running the wrapper
# and blocking the push. Warns and skips when the tool is absent; otherwise runs
# the command once and records a failure without aborting the remaining gates.
run_gate() {
  label="$1"
  probe="$2"
  cmd="$3"

  # Nothing to do when the installer resolved no command for this gate.
  [ -n "$cmd" ] || return 0

  # Fall back to deriving the probe from the command's leading real token.
  if [ -z "$probe" ]; then
    for tok in $cmd; do
      case "$tok" in
        *=*) continue ;;
        *) probe="$tok"; break ;;
      esac
    done
  fi

  if [ -n "$probe" ] && ! command -v "$probe" >/dev/null 2>&1; then
    echo "WARNING: '$probe' not found — skipping $label gate." >&2
    return 0
  fi

  echo "[$label] $cmd"
  if ! sh -c "$cmd"; then
    echo "ERROR: $label gate failed — push blocked (P-019)." >&2
    FAILED=1
  fi
}

# run_required_gate <label> <probe_tool> <install_command> <command>
# P-019 required-gate carve-out: identical to run_gate EXCEPT that an absent
# <probe_tool> is a FAILURE (not a skip). The failure names the install command
# and the `git push --no-verify` escape so a missing tool can never silently
# pass a gate that has been declared required.
run_required_gate() {
  label="$1"
  probe="$2"
  install_cmd="$3"
  cmd="$4"

  if ! command -v "$probe" >/dev/null 2>&1; then
    echo "ERROR: required tool '$probe' not found — $label gate cannot run (P-019)." >&2
    echo "       Install with: $install_cmd" >&2
    echo "       Or bypass this gate with: git push --no-verify" >&2
    FAILED=1
    return 0
  fi

  echo "[$label] $cmd"
  if ! sh -c "$cmd"; then
    echo "ERROR: $label gate failed — push blocked (P-019)." >&2
    FAILED=1
  fi
}

echo "Running local pre-push quality gates..."

run_gate "Lint" "cargo" "cargo clippy --all-targets -- -D warnings -D clippy::pedantic"
run_gate "Format" "cargo" "cargo fmt --all -- --check"
run_gate "Typecheck" "cargo" "cargo check --all-targets"
run_gate "Test" "cargo" "cargo dev-test"
run_gate "Build" "cargo" "cargo check --all-targets"

# Markdown lint (P-019 REQUIRED gate, P-008). Scope S1 — identical to CI so the
# local hook and CI cannot disagree: Markdown files changed vs the merge-base
# with the default branch, config .markdownlint.json, one pinned
# markdownlint-cli version. A missing linter FAILS the push (required gate).
if [ -f .markdownlint.json ]; then
  # Default-branch ref is resolved at RUN time and passed only through quoted
  # variables: a branch name is never rendered into the script text.
  md_ref="$(git symbolic-ref --quiet --short refs/remotes/origin/HEAD 2>/dev/null || true)"
  if [ -z "$md_ref" ]; then
    for cand in origin/main origin/master; do
      if git rev-parse --verify --quiet "$cand" >/dev/null 2>&1; then md_ref="$cand"; break; fi
    done
  fi
  md_base=""
  if [ -n "$md_ref" ]; then md_base="$(git merge-base "$md_ref" HEAD 2>/dev/null || true)"; fi
  if [ -n "$md_base" ]; then
    md_files="$(git diff --name-only --diff-filter=ACMR "$md_base" HEAD -- '*.md' ':(exclude).backlogit')"
    md_z="git diff -z --name-only --diff-filter=ACMR $md_base HEAD -- '*.md' ':(exclude).backlogit'"
  else
    md_files="$(git ls-files -- '*.md' ':(exclude).backlogit')"
    md_z="git ls-files -z -- '*.md' ':(exclude).backlogit'"
  fi
  # NUL-delimited list + `--` so file names can never be parsed as options or split.
  if [ -n "$md_files" ]; then
    run_required_gate "Docs" "markdownlint" "npm install -g markdownlint-cli@0.49.1" \
      "$md_z | xargs -0 markdownlint --config .markdownlint.json --"
  fi
fi

# Pipeline-topology gate (P-001/P-016 ambient invariant check).
#
# NON-SHIPMENT-SCOPED INVOCATION: no human-supplied --shipment is passed.
# The gate deterministically resolves its target (the currently-claimed
# active shipment from backlogit, or the current branch slug) and always
# runs `--phase ambient` here (at-most-one-active, validating the
# resolved target when one exists). No resolvable claimed shipment / zero
# active shipments -> PASSES (existence-guarded, non-blocking); a
# mismatched single active or two-or-more-active shipments still blocks
# fail-closed regardless of the advisory toggle below.
#
# Fail-closed by default: a gate failure blocks the push unless
# GSD_TOPOLOGY_GATE_BLOCKING=false is set in the environment. Single
# deterministic pass — no retry loop (circuit-breaker compatible).
# Absent 'gsd' -> warn+skip, never a hard failure.
GSD_PUSH_BIN=""
if command -v gsd >/dev/null 2>&1; then
  GSD_PUSH_BIN="gsd"
elif [ -x "./.gsd/gsd" ]; then
  GSD_PUSH_BIN="./.gsd/gsd"
elif [ -x "./.gsd/gsd.exe" ]; then
  GSD_PUSH_BIN="./.gsd/gsd.exe"
elif [ -x "./.bin/gsd" ]; then
  GSD_PUSH_BIN="./.bin/gsd"
elif [ -x "./.bin/gsd.exe" ]; then
  GSD_PUSH_BIN="./.bin/gsd.exe"
fi
if [ -n "$GSD_PUSH_BIN" ]; then
  echo "[Pipeline-Topology] gsd gate pipeline-topology --mode manual --phase ambient"
  if ! "$GSD_PUSH_BIN" gate pipeline-topology --mode manual --phase ambient; then
    if [ "${GSD_TOPOLOGY_GATE_BLOCKING:-true}" != "false" ]; then
      echo "ERROR: pipeline-topology gate failed — push blocked (P-001/P-016)." >&2
      FAILED=1
    else
      echo "WARNING: pipeline-topology gate failed (advisory override active) — push not blocked." >&2
      echo "  Clear GSD_TOPOLOGY_GATE_BLOCKING to restore fail-closed enforcement." >&2
    fi
  fi
else
  echo "WARNING: 'gsd' not found — skipping pipeline-topology gate." >&2
fi

if [ "$FAILED" -ne 0 ]; then
  echo "One or more quality gates failed. Fix them, or push with --no-verify to bypass." >&2
  exit 1
fi

echo "All local quality gates passed."
exit 0
